// Random walk around realistic soil values, so charts look alive.
// Ranges match the firmware's calibration clamps.
const BASE_LAT = env.get('AGRI_LAT') || -6.200000; // set to your field
const BASE_LNG = env.get('AGRI_LNG') || 106.816666;

let s = context.get('s') || { n: 200, p: 15, k: 120, ph: 6.5, moist: 50, lat: Number(BASE_LAT), lng: Number(BASE_LNG) };

function walk(v, step, min, max) {
    v += (Math.random() * 2 - 1) * step;
    return Math.min(max, Math.max(min, v));
}

s.n = walk(s.n, 10, 60, 350);
s.p = walk(s.p, 1, 5, 30);
s.k = walk(s.k, 5, 70, 170);
s.ph = walk(s.ph, 0.05, 5.0, 8.0);
s.moist = walk(s.moist, 2, 20, 90);
s.lat = walk(s.lat, 0.00002, s.lat - 0.001, s.lat + 0.001);
s.lng = walk(s.lng, 0.00002, s.lng - 0.001, s.lng + 0.001);
context.set('s', s);

// Raw ADC counts, back-calculated from the ADS1115 calibration.
const npk1 = Math.round((46510 - s.n) / 8.1731);
const npk2 = npk1 + Math.round(Math.random() * 40 - 20);
const moistRaw = Math.round(11940 - (s.moist / 100) * (11940 - 4680));
const phRaw = Math.round(300 + Math.random() * 50);

const gpsValid = Math.random() > 0.1; // 10% of readings without a GPS fix

const out = [
    { topic: 'agrisoil/val/moist', payload: s.moist.toFixed(2) },
    { topic: 'agrisoil/val/ph', payload: s.ph.toFixed(2) },
    { topic: 'agrisoil/val/nit', payload: s.n.toFixed(2) },
    { topic: 'agrisoil/val/phos', payload: s.p.toFixed(2) },
    { topic: 'agrisoil/val/kal', payload: s.k.toFixed(2) },
    { topic: 'agrisoil/raw/moist', payload: String(moistRaw) },
    { topic: 'agrisoil/raw/ph', payload: String(phRaw) },
    { topic: 'agrisoil/raw/npk1', payload: String(npk1) },
    { topic: 'agrisoil/raw/npk2', payload: String(npk2) }
];
if (gpsValid) {
    out.push({ topic: 'agrisoil/loc/lat', payload: s.lat.toFixed(6) });
    out.push({ topic: 'agrisoil/loc/lng', payload: s.lng.toFixed(6) });
}
return [out];

// The ESP32 expects plain text: just the port number.
// Real setup: today's ngrok TCP port. Local test: the broker's port.
msg.payload = String(global.get('ngrokPort') || env.get('AGRI_MQTT_PORT') || 1883);
msg.headers = { 'Content-Type': 'text/plain' };
return msg;
